#include <bits/stdc++.h>
using namespace std;

int maxScore(vector<int>& cardPoints, int k) {
    int n = cardPoints.size(), keep = n - k;
    int total = accumulate(cardPoints.begin(), cardPoints.end(), 0);
    int window = accumulate(cardPoints.begin(), cardPoints.begin() + keep, 0);
    int best = window;
    for (int i = keep; i < n; ++i) {
        window += cardPoints[i] - cardPoints[i - keep];
        best = min(best, window);
    }
    return total - best;
}

