class Solution {
    public int maxScore(int[] cardPoints, int k) {
        int n = cardPoints.length, keep = n - k;
        int total = 0, window = 0;
        for (int v : cardPoints) total += v;
        for (int i = 0; i < keep; ++i) window += cardPoints[i];
        int best = window;
        for (int i = keep; i < n; ++i) {
            window += cardPoints[i] - cardPoints[i - keep];
            best = Math.min(best, window);
        }
        return total - best;
    }
}
